  [2831] = { "胸、脚、手、足に装備するアイテムのStamina値を1、Armor値を8、永続的に上げます。", nil, 0x3fd0219d, nil, "um" },
  [2832] = { "胸、脚、手、足に装備するアイテムのStamina値を2、armor値を16、永続的に上げます。", nil, 0x3353445a, nil, "um" },
  [2833] = { "胸、脚、手、足に装備するアイテムのStaminaの値を$N1、armorの値を$N2永続的に増加させます。アイテムレベル$N3以上のアイテムにのみ使用できます。", nil, 0x4484080b, nil, "um" },
  [2835] = { "武器に毒を塗ります。毒は$N1分持続します。\n攻撃のたびに$N2%の確率で敵を毒に冒し、$D1かけて$N3のNatureダメージを与えます。1体の対象に$N5回まで重なります。チャージ$N6回。", nil, 0x1bbff3d1, nil, "um" },
  [2836] = { "罠を発見するチャンスが大きく\n上昇します。", "罠を探知しています。", 0xaf39679d, 0x61482710, "uu" },
  [2837] = { "武器に毒を塗ります。毒は$N1分持続します。\n攻撃のたびに$N2%の確率で敵を毒に冒し、$D1かけて$N3のNatureダメージを与えます。1体の対象に$N5回まで重なります。チャージ$N6回。", nil, 0x02335a7f, nil, "um" },
  [2842] = { "入手した材料や店で買った材料を使って、毒を作り調合できます。", nil, 0x7af047c0, nil, "um" },
  [2860] = { "敵に稲妻を放ってNatureダメージを$N1与え、その後近くにいる別の敵へ跳躍します。跳躍するたびにダメージが$N2%減少します。合計$N3体の対象に効果があります。", nil, 0x17000523, nil, "um" },
  [2870] = { "対象の病気を$N1個治療します。", nil, 0xc25d1459, nil, "um" },
  [2871] = { "$D1の間、対象を病気に対して免疫にし、既にかかっている病気をすべて治療します。", "Diseaseに対する免疫があります。", 0x781ea60b, 0x757e4c3b, "uu" },
  [2878] = { "対象のアンデッドの敵を、最大$D1の間強制的に逃走させます。ダメージを受けると効果が中断されることがあります。同時に退散させられる対象は1体だけです。", "逃げ出さずにはいられません。", 0x4618a73c, 0x7a42271d, "uu" },
  [2893] = { "$D1の間、対象の毒効果を$N1個治療しようと試み、さらに$N3秒ごとに毒効果を$N2個治療しようと試みます。", "$N2秒ごとに毒を$N1つ治療しようとします。", 0x2d04dd2c, 0x628fb079, "uu" },
  [2908] = { "対象の獣をなだめ、あなたを攻撃してくる距離を$N1ヤード縮めます。レベル40以下のBeastにのみ有効です。効果時間は$D1です。", "目標が攻撃してくる距離が短くなります。", 0xbe4c812f, 0x6f0854bf, "uu" },
  [2912] = { "対象に$N1のArcaneダメージを与えます。", nil, 0xf284a035, nil, "um" },
  [2941] = { "敵を焼き、$N1のFireダメージを与え、さらに$D1かけて$N2のFireダメージを与えます。", "$N2秒ごとに$N1のFireダメージを受けます。", 0xe3931f57, 0x0d35ca56, "uu" },
  [2943] = { nil, "近接攻撃力が$N1低下しています。", nil, 0x100ea149, "mu" },
  [2944] = { "対象を病に冒し、$D1かけて$N1のShadowダメージを与えます。Devouring Plagueによるダメージは術者を回復します。", "$N2秒ごとに$N1のダメージを与え、術者を回復します。", 0x34935b22, 0xdfe21d0d, "uu" },
  [2947] = { "対象を炎の盾で包みます。対象への攻撃があるたびに、攻撃者に$N1のFireダメージを与えます。効果時間は$D1です。ペットは自身にFire Shieldをかけられません。", "攻撃を受けると、攻撃者に$N1のFireダメージを与えます。", 0x9dc0d206, 0x8a7fa492, "uu" },
  [2948] = { "敵を焼き払い、$N1Fireダメージを与えます。", nil, 0x1986adcb, nil, "um" },
  [2970] = { "$D1の間、味方の対象が透明な者を見破れるようにします。", "Invisibilityを探知します。", 0x2861dd87, 0x09a3bf44, "uu" },
  [2973] = { "近接武器ダメージに$N1を加えたダメージを与える強力な攻撃です。", nil, 0xc5af8171, nil, "um" },
  [2974] = { "$N1のダメージを与え、$D1の間、敵の対象の移動速度を$N2%下げます。", "移動速度が$N1%低下しています。", 0x6615693d, 0x08fe36e7, "uu" },
  [2983] = { "$D1の間、ローグの移動速度を$N1%上げます。隠密状態は解除されません。", "移動速度が$N1%上昇しています。", 0xf73d45b6, 0xd5c3ac7c, "uu" },
})
